// Packs kb/ into src/kb-bundle.ts so the Worker carries the knowledge base without a filesystem.
// Runs before typecheck, tests, dev and deploy. Edit files in kb/, never the generated file.
import { readdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const kb = join(root, "kb");
const files = {};
const walk = (dir) => {
  for (const name of readdirSync(dir).sort()) {
    const abs = join(dir, name);
    if (statSync(abs).isDirectory()) walk(abs);
    else if (/\.(md|ya?ml)$/.test(name)) files[relative(kb, abs).split("\\").join("/")] = readFileSync(abs, "utf8");
  }
};
walk(kb);
writeFileSync(
  join(root, "src", "kb-bundle.ts"),
  `// Generated by scripts/bundle-kb.mjs from kb/. Do not edit.\nexport const KB_FILES: Record<string, string> = ${JSON.stringify(files, null, 2)};\n`,
);
console.log(`Bundled ${Object.keys(files).length} knowledge base files.`);
